export function isCtaAmbito(value: string | undefined): value is CtaAmbito {
  return value === "preinscricao" || value === "contacto";
}

export function ctaDestino(tipo: string): CtaDestino {
  return CTA_BY_TIPO[tipo] ?? {
    ambito: "contacto",
    href: SECRETARIA_HREF,
    funcao: "Falar com a secretaria",
  };
}

export function buildCtaVars(p: { nome: string; email: string; curso: string; turma: string }) {
  const origin = config.appOrigin.replace(/\/$/, "");
  const q = new URLSearchParams({ email: p.email, curso: p.curso, turma: p.turma });
  return {
    nome: p.nome,
    email: p.email,
    curso: p.curso,
    turma: p.turma,
    preinscricao_url: `${origin}/pre-inscricao?${q.toString()}`,
    secretaria_url: SECRETARIA_HREF,
  };
}

export function fillCtaHref(href: string, vars: Record<string, string>) {
  return href.replace(/\{\{(\w+)\}\}/g, (_, k: string) => {
    if (k === "preinscricao_url" || k === "secretaria_url") return vars[k] ?? "";
    return encodeURIComponent(vars[k] ?? "");
  });
}

import { type CtaAmbito, isCtaAmbito } from "./emailCta.js";

function decode(text: string) {
  return text
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, "&");
}

function esc(s: string) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

export function parseEmailXml(xml: string): { linhas: string[]; cta: string; href: string; ambito?: CtaAmbito } {
  const src = xml?.trim() || "";
  const tag = src.match(/<cta\b([^>]*)>([\s\S]*?)<\/cta>/i);
  const attrs = tag?.[1] ?? "";
  const cta = decode((tag?.[2] ?? "").trim());
  const href = decode((attrs.match(/\bhref\s*=\s*"([^"]*)"/i)?.[1] ?? "").trim());
  const ambitoRaw = (attrs.match(/\bambito\s*=\s*"([^"]*)"/i)?.[1] ?? "").trim();
  const ambito = isCtaAmbito(ambitoRaw) ? ambitoRaw : undefined;
  const linhas = [...src.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)].map(m =>
    decode(
      m[1]
        .replace(/<br\s*\/?>/gi, "\n")
        .replace(/<\/?(?:strong|em)>/gi, "")
        .replace(/<[^>]+>/g, ""),
    ).trim(),
  ).filter(Boolean);
  return { linhas, cta, href, ambito };
}

export function linesToXml(linhas: string[], cta: string, href = "", ambito?: CtaAmbito): string {
  const ps = linhas.filter(Boolean).map(l => `  <p>${esc(l)}</p>`).join("\n");
  const attrs = [ambito ? ` ambito="${ambito}"` : "", href ? ` href="${esc(href)}"` : ""].join("");
  return `<email>\n${ps}\n  <cta${attrs}>${esc(cta)}</cta>\n</email>\n`;
}

import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";

const path = [resolve(process.cwd(), ".env"), resolve(process.cwd(), "../.env")].find(existsSync);
if (path) {
  for (const line of readFileSync(path, "utf8").split(/\r?\n/)) {
    const t = line.trim();
    if (!t || t.startsWith("#")) continue;
    const i = t.indexOf("=");
    if (i < 1) continue;
    const key = t.slice(0, i).trim();
    let val = t.slice(i + 1).trim();
    if ((val.startsWith("\"") && val.endsWith("\"")) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }
    if (process.env[key] == null) process.env[key] = val;
  }
}

